N=[]
def focus(key,title,chapter,x,y,icon,parents=(),description='',effects=(),requirements=(),history='Historical precedent',exclusive=(),days=35,world=None):
    row=dict(id='COLDWAR_USA_KS_'+key,key=key,title=title,chapter=chapter,x=x,y=y,icon=icon,
             parents=list(parents),description=description,effects=list(effects),requirements=list(requirements),
             history=history,exclusive=list(exclusive),days=days,world=world,existing=False,
             prerequisite_groups=[list(parents)] if parents else [])
    N.append(row);return row

def effect(country,label,value='',kind='effect'):
    return dict(country=country,label=label,value=value,kind=kind)

