for tree in nodes(source):
    if tree.key!='focus_tree':continue
    for f in tree.children():
        fid=field(f.children(),'id','')
        if f.key!='focus' or not str(fid).startswith('COLDWAR_USA_gulf_'):continue
        suffix=fid.removeprefix('COLDWAR_USA_gulf_')
        if suffix=='contacts':continue
        parents=[field(c.children(),'focus') for c in f.children() if c.key=='prerequisite']
        groups=[[z.value for z in c.children() if z.key=='focus'] for c in f.children() if c.key=='prerequisite']
        x,y=gulf_positions[suffix]
        r=focus('gulf_'+suffix,labels.get(fid,suffix.replace('_',' ').title()),'gulf',x,y,11 if suffix in ('desert_shield','desert_storm','coalition') else 3,
                ['gulf_'+p.removeprefix('COLDWAR_USA_gulf_') for group in groups for p in group],labels.get(fid+'_desc','Existing Gulf programme.'),
                [],history='Existing installed branch',days=round(float(field(f.children(),'cost','5'))*7))
        r.update(existing=True,id=fid,prerequisite_groups=groups,exclusive=['gulf_'+z.value.removeprefix('COLDWAR_USA_gulf_') for c in f.children() if c.key=='mutually_exclusive' for z in c.children() if z.key=='focus'])
        if suffix in ('desert_shield','desert_storm','coalition'):
            r['requirements']=['An unresolved Iraqi attack on Kuwait, including occupation after capitulation','Independent of all Kurdish support focuses']
        if suffix=='desert_storm':r['effects']=[effect('USA','War Goal against Iraq','Liberation of Kuwait')]

